def algorithm(func, dim, lb, ub, budget, rng):
    def clip_candidate(candidate):
        return np.clip(candidate, lb, ub)

    x = np.array(rng.uniform(lb, ub, (1, dim)))
    T = 1000
    alpha = 0.99

    for _ in range(budget):
        y = clip_candidate(x + rng.normal(size=x.shape))
        f_y = func(y)
        f_x = func(x)

        if np.random.rand() < np.exp((f_x - f_y) / T):
            x = y
        else:
            pass

        if _ % 100 == 0:
            T *= alpha

    return clip_candidate(x)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = clip(rng.uniform(lb, ub, size=dim))
    best_x = x.copy()

    for _ in range(budget):
        x = clip(x + 0.1 * rng.normal(size=dim))
        fx = func(x)

        if fx < func(best_x):
            best_x = x

        x = (x + best_x) / 2
        fx = func(clip(x))

        if fx < func(best_x):
            best_x = x

    return best_x
